def promote_recipes(apps, schema_editor):
    pipeline_model = apps.get_model("overbae", "DatasetPipeline")
    run_model = apps.get_model("overbae", "DatasetPipelineRun")
    seen = set()
    for recipe in (
        pipeline_model.objects.select_related("dataset").order_by("created_at", "pk").iterator()
    ):
        recipe.project_id = recipe.dataset.project_id
        recipe.family = recipe.pk
        key = (recipe.project_id, recipe.request_key)
        if key in seen:
            recipe.request_key = f"migrated-{recipe.pk}"
        seen.add((recipe.project_id, recipe.request_key))
        recipe.fingerprint = hashlib.sha256(
            json.dumps(
                {
                    "name": recipe.name,
                    "steps": recipe.steps,
                    "package": "",
                    "pipeline": "",
                    "expected_revision": None,
                    "derived_from": "",
                },
                sort_keys=True,
                allow_nan=False,
            ).encode()
        ).hexdigest()
        recipe.save(update_fields=["project", "family", "request_key", "fingerprint"])
    for run in run_model.objects.all().iterator():
        run.attempt = uuid.uuid4()
        run.save(update_fields=["attempt"])


